publicExamples.source:
@post('/items', {
  payload: {title: $title},
  params: {source: 'toolbar'},
  pending: 'saving',
  error: 'saveError',
  retry: 'error',
  retryMaxCount: 2,
  requestCancellation: 'cleanup'
})

@ui.toast.show({
    title: 'Saved',
    description: 'Your changes are live.',
    variant: 'success'
  })
